tool_input.command:
go version && mkdir -p /tmp/clampcheck && cat > /tmp/clampcheck/snap_test.go <<'EOF'
package task

import (
	"fmt"
	"os"
	"testing"
)

func TestSnapshot(t *testing.T) {
	f, _ := os.Create(os.Getenv("SNAP"))
	defer f.Close()
	r := []int{-1000, -60, -51, -50, -1, 0, 1, 9, 10, 24, 25, 50, 90, 91, 99, 100, 101, 150, 151, 200, 239, 240, 319, 320, 400, 401, 2160, 2161, 3840, 3841, 10000}
	for _, a := range r {
		fmt.Fprintln(f, "B", a, Brightness(a), Volume(a), Zoom(a))
		for _, b := range r {
			w, h := Frame(a, b)
			fmt.Fprintln(f, "P", a, b, Contrast(a, b), Balance(a, b), Mix(a, b), w, h)
			for _, c := range r {
				fmt.Fprintln(f, "T", a, b, c, Scroll(a, b, c))
			}
			if b != 0 {
				fmt.Fprintln(f, "Pc", a, b, Percent(a, b))
			}
		}
	}
}
EOF
cp /tmp/clampcheck/snap_test.go ./snap_test.go && SNAP=/tmp/clampcheck/before.txt go test -run TestSnapshot . && wc -l /tmp/clampcheck/before.txt
